Translate("zhCN", "ashenvale", {
	title = "灰谷",
	aliases = { "灰谷森林" },
	sections = {
		{
			title = "概述",
			text = [=[灰谷是{link:night-elves}暗夜精灵{/link}的大森林，位于{link:kalimdor}卡利姆多{/link}北部，是一片高树参天、银湖点点、白色废墟散落的土地。它西起{link:the-zoram-strand}佐拉姆海岸{/link}的灰色大海，东至将它与{link:azshara}艾萨拉{/link}分开的河流。{link:darkshore}黑海岸{/link}和{link:felwood}费伍德森林{/link}在其北，{link:stonetalon-mountains}石爪山脉{/link}和{link:the-barrens}贫瘠之地{/link}在其南。一万年来，暗夜精灵一直把它当作神圣的{link:moonglade}林地{/link}守护。如今它不再只对他们而言神圣。{link:horde}部落{/link}的斧声回荡在它东部的{link:stranglethorn-vale}山谷{/link}中，这片森林已成为精灵与{link:orcs}兽人{/link}之间最古老、也最惨烈的战场。]=],
		},
		{
			title = "起源",
			text = [=[灰谷的树木比任何编年史都要古老。在{link:great-sundering}大分裂{/link}之前，精灵的城市沿着它的西岸而立，{link:the-zoram-strand}佐拉姆{/link}城眺望着大海。{link:well-of-eternity}永恒之井{/link}被毁时，海水上涨，吞没了佐拉姆，古老神殿的废墟散落在林间：{link:the-ruins-of-ordil-aran}奥迪拉兰{/link}、{link:bathran-s-haunt}巴斯兰鬼屋{/link}、{link:the-ruins-of-stardust}星尘废墟{/link}，以及东方的{link:xavian}萨维亚{/link}城。战后，{link:night-elves}暗夜精灵{/link}定居在{link:mount-hyjal}海加尔山{/link}的阴影下，投身于{link:cenarius}塞纳留斯{/link}与德鲁伊之道。德鲁伊在{link:emerald-dream}翡翠梦境{/link}中沉睡时，{link:tyrande-whisperwind}泰兰德·语风{/link}的{link:sentinels}哨兵{/link}在漫长守望的岁月里看守着这片森林。没有编年史记载{link:astranaar}阿斯特兰纳{/link}或森林中的其他村落最初建于何时。]=],
		},
		{
			title = "当今",
			text = [=[自{link:third-war}第三次战争{/link}以来，灰谷再未有过和平。{link:sentinels}哨兵{/link}守着{link:astranaar}阿斯特兰纳{/link}、{link:maestra-s-post}迈斯特拉岗哨{/link}、{link:silverwind-refuge}银风避难所{/link}和{link:forest-song}林歌神殿{/link}，但她们兵力单薄，道路漫长。{link:thistlefur-village}蓟皮{/link}与污林的{link:furbolgs}熊怪{/link}曾是精灵的朋友，如今却被一种从{link:felwood}费伍德森林{/link}蔓延而下的腐化所毒害，袭击每一位旅人。{link:satyrs}萨特{/link}占据着{link:night-run}夜道谷{/link}、{link:satyrnaar}萨提纳尔{/link}和{link:xavian}萨维亚{/link}。{link:naga}纳迦{/link}回到了{link:the-zoram-strand}佐拉姆{/link}的水下废墟，一个{link:twilight-s-hammer}暮光之锤{/link}的教团聚集在{link:blackfathom-deeps}黑暗深渊{/link}被淹没的大厅中。在东方，战歌的{link:orcs}兽人{/link}在{link:splintertree-post}碎木岗哨{/link}的守护下为{link:horde}部落{/link}伐木。他们又在西岸建起了第二座前哨，{link:zoram-gar-outpost}佐拉姆加{/link}。每倒下一棵树，精灵便以箭矢回应，两个种族之间的战争每个季节都向林中更深处蔓延一些。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:night-elves}暗夜精灵{/link}。{/b}{link:sentinels}哨兵{/link}、德鲁伊和女祭司守卫着森林中的村落，为保全森林而战。
• {b}树妖。{/b}{link:cenarius}塞纳留斯{/link}的女儿们仍在{link:raynewood-retreat}林中树居{/link}和{link:the-shrine-of-aessina}艾森娜神殿{/link}的林间空地上起舞。
• {b}{link:horde}部落{/link}。{/b}战歌的{link:orcs}兽人{/link}与{link:trolls}巨魔{/link}、{link:tauren}牛头人{/link}和地精并肩，守着{link:splintertree-post}碎木岗哨{/link}、东部的伐木营地和海岸上的{link:zoram-gar-outpost}佐拉姆加前哨站{/link}。
• {b}{link:forsaken}被遗忘者{/link}。{/b}{link:undercity}幽暗城{/link}的药剂师已悄悄潜入精灵的兽穴与废墟。
• {b}{link:furbolgs}熊怪{/link}。{/b}北方的{link:thistlefur-village}蓟皮{/link}与南方的污林已陷入疯狂，还有追随一位野蛮之王的{link:bloodtooth-camp}血牙{/link}。
• {b}{link:satyrs}萨特{/link}。{/b}魔麝、凄心和{link:xavian}萨维亚{/link}的萨特在东方的残破神殿中崇拜恶魔。
• {b}{link:naga}纳迦{/link}。{/b}怒尾纳迦出没于{link:the-zoram-strand}佐拉姆海岸{/link}和{link:blackfathom-deeps}黑暗深渊{/link}的水域。
• {b}恶魔。{/b}恶魔卫士和地狱火仍在{link:mannoroth}玛诺洛斯{/link}陨落的峡谷中游荡。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:the-drowned-city}沉没之城{/link}。{/b}{link:great-sundering}大分裂{/link}时，大海吞没了{link:the-zoram-strand}佐拉姆{/link}。它的统治者、它的戒指和它的秘密都随之沉没。
• {b}漫长守望。{/b}一万年间，德鲁伊沉睡，{link:sentinels}哨兵{/link}守护着灰谷，森林变得幽深而宁静。
• {b}{link:orcs}兽人{/link}到来。{/b}{link:third-war}第三次战争{/link}中，{link:grom-hellscream}格罗姆·地狱咆哮{/link}的兽人来到灰谷，为他们的新家园伐木。哨兵予以反击，{link:cenarius}塞纳留斯{/link}亲自起身保卫森林。格罗姆和他的战士喝下了被{link:mannoroth}玛诺洛斯{/link}之血污染的泉水，在那股狂怒中杀死了这位半神。此后，在东部森林的一条峡谷中，格罗姆杀死了玛诺洛斯，将他的族人从血之诅咒中解放出来，自己却伤重而亡。
• {b}{link:mount-hyjal}海加尔山{/link}。{/b}在{link:battle-of-mount-hyjal}海加尔山之战{/link}中，精灵、兽人和{link:humans}人类{/link}共同对抗{link:archimonde}阿克蒙德{/link}，军团被击溃。那一日的同盟并未在胜利后延续。
• {b}当今。{/b}{link:horde}部落{/link}仍在砍伐灰谷的树木。{link:night-elves}暗夜精灵{/link}从未接受这一点。]=],
		},
		{
			title = "森林传说",
			text = [=[• 据说，保存在费伍德边境附近一座残破神殿中的{link:the-howling-vale}梅尔桑迪斯{/link}之书，会在书页上自行记下重大事件。无人知晓其中缘由。
• 一个名叫{link:krog}克罗格{/link}的{link:furbolgs}熊怪{/link}独自住在{link:mystral-lake}密斯特拉湖{/link}畔。他只与同族交谈，并把族人的毁灭归咎于精灵。
• {link:splintertree-post}碎木{/link}的猎手们传说森林中有三头巨兽：熊{link:ursangous}乌萨苟斯{/link}、夜刃豹{link:shadumbra}猎影{/link}和角鹰兽{link:sharptalon}尖爪{/link}。将三者全部猎杀，是对任何猎手价值的考验。
• {link:satyrs}萨特{/link}从树妖手中偷走了{link:cenarius}塞纳留斯{/link}之枝，树妖至今没有原谅这件事。]=],
		},
	},
})

Translate("zhCN", "astranaar", {
	title = "阿斯特兰纳",
	sections = {
		{
			title = "概述",
			text = [=[阿斯特兰纳是{link:night-elves}暗夜精灵{/link}在{link:ashenvale}灰谷{/link}的主要城镇。它坐落于森林中心一座湖中的小岛上，以白石桥梁与湖岸相连。{link:raene-wolfrunner}莱恩·狼行者{/link}在这里统领本地的{link:sentinels}哨兵{/link}，斥候从这里出发，奔赴森林的每一个角落。镇上有一家旅店、一处角鹰兽栖木，还有一个精灵工匠的小集市。它也已成为一座忧虑之城。哨兵报告说北方的{link:furbolgs}熊怪{/link}数量日增，一户人家中躺着一个患病的孩子，而与{link:horde}部落{/link}的战争每个季节都离它的桥梁更近一步。]=],
		},
	},
})

Translate("zhCN", "maestra-s-post", {
	title = "迈斯特拉岗哨",
	aliases = { "迈斯特拉" },
	sections = {
		{
			title = "概述",
			text = [=[迈斯特拉岗哨是{link:ashenvale}灰谷{/link}西北部的一座精灵小前哨，位于从{link:darkshore}黑海岸{/link}南下的道路上。它是从{link:auberdine}奥伯丁{/link}来的旅人在森林中找到的第一处庇护所。{link:sentinels}哨兵{/link}在此守望，德鲁伊{link:orendil-broadleaf}奥雷迪尔·阔叶{/link}在这里调配他的药剂。一位{link:humans}人类{/link}圣骑士，{link:delgren-the-purifier}净化者德尔格伦{/link}，把这里当作他对抗黑纹教团之战的据点，他的信使把补给向北送往奥伯丁。刚从{link:emerald-dream}翡翠梦境{/link}中醒来的德鲁伊会被送到这里接应。]=],
		},
	},
})

Translate("zhCN", "bathran-s-haunt", {
	title = "巴斯兰鬼屋",
	sections = {
		{
			title = "概述",
			text = [=[巴斯兰鬼屋是{link:ashenvale}灰谷{/link}北部丘陵中的一处精灵废墟，就在{link:darkshore}黑海岸{/link}边界以南。一种名为巴斯兰之发的植物曾生长在它的石块间，德鲁伊视之为治疗心灵疾病的珍贵良药。这处废墟已不再空荡。{link:forsaken}被遗忘者{/link}在残墙之间扎下营地，他们的草药师采集这里生长的植物，另有图谋。{link:maestra-s-post}迈斯特拉岗哨{/link}的德鲁伊对他们的出现深感不安。]=],
		},
	},
})

Translate("zhCN", "the-ruins-of-ordil-aran", {
	title = "奥迪拉兰废墟",
	aliases = { "奥迪拉兰" },
	sections = {
		{
			title = "概述",
			text = [=[奥迪拉兰是{link:ashenvale}灰谷{/link}北部一座古代精灵的残破城镇，位于{link:maestra-s-post}迈斯特拉岗哨{/link}东北。它的名字令人想起{link:darkshore}黑海岸{/link}的双子城镇{link:ameth-aran}亚米萨兰{/link}和{link:bashal-aran}巴莎兰{/link}，那两座城镇是在{link:queen-azshara}艾萨拉女王{/link}的时代为上层精灵而建的。如今，黑纹教团的术士在它的石块间挖掘。其中一人带着一颗灵魂宝石，宝石中藏着教团力量的秘密，直到{link:delgren-the-purifier}净化者德尔格伦{/link}派出一位勇士将它夺走。]=],
		},
	},
})

Translate("zhCN", "the-zoram-strand", {
	title = "佐拉姆海岸",
	aliases = { "佐拉姆" },
	sections = {
		{
			title = "概述",
			text = [=[佐拉姆海岸是{link:ashenvale}灰谷{/link}的{link:western-strand}西部海岸{/link}，一片灰沙与断柱相间的海滩。海浪之下沉睡着佐拉姆，一座在{link:great-sundering}大分裂{/link}中被大海吞没的精灵之城。漫长岁月里，它几乎被人遗忘。如今{link:naga}纳迦{/link}回到了这里，无人知道她们在寻找什么。怒尾纳迦与九头蛇一起占据着海岸及其岛屿。在海岸北端，一座半沉入海中的巨大神殿通往{link:blackfathom-deeps}黑暗深渊{/link}的深处。]=],
		},
	},
})

Translate("zhCN", "zoram-gar-outpost", {
	title = "佐拉姆加前哨站",
	aliases = { "佐拉姆加" },
	sections = {
		{
			title = "概述",
			text = [=[佐拉姆加是{link:horde}部落{/link}在{link:the-zoram-strand}佐拉姆海岸{/link}的前哨，一座建在海边狭长陆地上的{link:orcs}兽人{/link}与{link:trolls}巨魔{/link}营地。它的建立是为了替部落夺取{link:ashenvale}灰谷{/link}西岸，并监视{link:naga}纳迦{/link}和{link:blackfathom-deeps}黑暗深渊{/link}的废墟。{link:karang-amakkar}卡拉恩·阿玛卡{/link}统领此地。{link:earthen-ring}大地之环{/link}的巨魔{link:je-neu-sancrea}耶努萨克雷{/link}在岸边研究大海。营地处境艰难。纳迦不断袭扰，一头巨大的九头蛇不止一次发动攻击，而{link:thistlefur-village}蓟皮{/link}{link:furbolgs}熊怪{/link}横亘在它与{link:splintertree-post}碎木岗哨{/link}之间。]=],
		},
	},
})

Translate("zhCN", "lake-falathim", {
	title = "法拉希姆湖",
	sections = {
		{
			title = "概述",
			text = [=[法拉希姆湖位于{link:ashenvale}灰谷{/link}西部的山脚下。湖中的岛上曾有一座神殿，精灵在那里保存着一颗发光的宝石，直到神殿被攻陷。如今盐沫部族的{link:murlocs}鱼人{/link}占据着湖岸。精灵{link:teronis}泰洛尼斯{/link}正是来到这里寻找那颗宝石，他的朋友们也正是在这里发现了他的尸体：被鱼人的爪子撕裂，却无人触碰地躺在岛上。]=],
		},
	},
})

Translate("zhCN", "the-shrine-of-aessina", {
	title = "艾森娜神殿",
	aliases = { "艾森娜神殿", "艾森娜" },
	sections = {
		{
			title = "概述",
			text = [=[艾森娜神殿是{link:ashenvale}灰谷{/link}西部群山中一片隐秘的林间空地，四周峭壁环绕，只有少数小径可达。其中矗立着一座蕴含强大而微妙力量的神殿，森林的魔力在此汇聚。树妖住在那里，其中有{link:therysil}瑟瑞希尔{/link}和{link:illiyana}伊莉亚娜{/link}，{link:sentinel-melyria-frostshadow}哨兵梅丽瑞亚·霜影{/link}守望着这片空地。想要重新激活魔法的人会来到这里，把他们的造物放入神殿的水盆中，等待光芒亮起。]=],
		},
	},
})

Translate("zhCN", "fire-scar-shrine", {
	title = "火痕神殿",
	aliases = { "火痕" },
	sections = {
		{
			title = "概述",
			text = [=[火痕神殿是{link:ashenvale}灰谷{/link}西南部的一处极恶之地。它的土地被焚毁，树木已经死去。{link:orcs}兽人{/link}术士{link:ilkrud-magthrull}伊克鲁德·玛格苏尔{/link}在这里设下巢穴，恶魔听从他的召唤。一个名叫阿克瑞鲁斯的恶魔在灰烬中行走。精灵曾把伊克鲁德视为一个小麻烦而已。直到{link:delgren-the-purifier}净化者德尔格伦{/link}得知，这名术士记录着黑纹教团的计划，情况才有所改变。]=],
		},
	},
})

Translate("zhCN", "thistlefur-village", {
	title = "蓟皮村",
	aliases = { "蓟皮洞穴", "蓟皮" },
	sections = {
		{
			title = "概述",
			text = [=[蓟皮村是蓟皮{link:furbolgs}熊怪{/link}的家园，位于{link:astranaar}阿斯特兰纳{/link}以北。他们的小屋散布在林间，在村子的尽头，一个名为蓟皮洞穴的山洞深入山丘。蓟皮熊怪并非一直是敌人，但他们如今已被腐化，最近几个月数量大增。{link:sentinels}哨兵{/link}担心他们会大胆到进攻阿斯特兰纳本身。{link:horde}部落{/link}也惧怕他们，因为这座村子阻断了{link:zoram-gar-outpost}佐拉姆加{/link}与{link:splintertree-post}碎木{/link}之间的道路。]=],
		},
	},
})

Translate("zhCN", "iris-lake", {
	title = "伊瑞斯湖",
	sections = {
		{
			title = "概述",
			text = [=[伊瑞斯湖位于{link:astranaar}阿斯特兰纳{/link}以东，是一片宁静的水域，湖心有一座小岛。岛上有一块名为艾露恩之泪的石头，世上别处再也找不到。德鲁伊说它能洗去腐化。当{link:pelturas-whitemoon}皮尔图拉斯·怀特姆恩{/link}的女儿被噩梦折磨而病倒时，正是伊瑞斯湖的这块泪石平复了她的噩梦。]=],
		},
	},
})

Translate("zhCN", "the-ruins-of-stardust", {
	title = "星尘废墟",
	aliases = { "星尘废墟" },
	sections = {
		{
			title = "概述",
			text = [=[星尘废墟位于{link:astranaar}阿斯特兰纳{/link}以南，坐落在南部森林的树木之间。那里除了碎石几乎什么也没有留下。然而，废墟间聚积着一种霜冻的尘土，德鲁伊知道它能退烧。这个地名比任何记载都古老，精灵只说它因这尘土而得名。]=],
		},
	},
})

Translate("zhCN", "mystral-lake", {
	title = "密斯特拉湖",
	sections = {
		{
			title = "概述",
			text = [=[密斯特拉湖是{link:ashenvale}灰谷{/link}南部一片开阔的水域，靠近通往{link:stonetalon-mountains}石爪山脉{/link}的{link:the-talondeep-path}石爪小径{/link}入口。它的湖水活了过来。被污染的{link:elements}元素{/link}生物从水中升起，攻击任何靠近的东西，森林与石爪之间的道路几乎已经断绝。湖上的一座凉亭俯瞰着岸边的精灵避难所，{link:sentinels}哨兵{/link}和{link:horde}部落{/link}都很在意谁在那里观望。湖的南岸住着{link:krog}克罗格{/link}，一个逃脱了族人所受腐化的{link:furbolgs}熊怪{/link}。]=],
		},
	},
})

Translate("zhCN", "silverwind-refuge", {
	title = "银风避难所",
	aliases = { "银风" },
	sections = {
		{
			title = "概述",
			text = [=[银风避难所是{link:night-elves}暗夜精灵{/link}在{link:mystral-lake}密斯特拉湖{/link}南岸的一座村落。它有自己的商人、训练师和炼{link:ginro-hearthkindle}金{/link}师，还有一处角鹰兽栖木。{link:sentinel-velene-starstrike}哨兵维尔莉妮·星坠{/link}统领着这里的守卫。近来避难所不得安宁，因为旁边的湖中满是污秽的{link:elements}元素{/link}生物。维琳已查明是谁制造了它们，并发誓要让他付出代价。]=],
		},
	},
})

Translate("zhCN", "fallen-sky-lake", {
	title = "坠星湖",
	sections = {
		{
			title = "概述",
			text = [=[坠星湖位于{link:ashenvale}灰谷{/link}东南部。精灵曾在湖岸收集月石，那些石头从天而降，蕴含着月亮的力量。后来影丛来了。它们是扭曲的树人，它们的先知把每一块坠落的月石都收进了自己的宝藏。精灵从此不再前往这座湖。]=],
		},
	},
})

Translate("zhCN", "raynewood-retreat", {
	title = "林中树居",
	aliases = { "雷恩木" },
	sections = {
		{
			title = "概述",
			text = [=[林中树居是{link:ashenvale}灰谷{/link}中心的一片{link:razorfen-downs}高地{/link}林苑，顶上矗立着一棵同名的巨树。被称为欢笑姐妹的树妖在林间空地上嬉戏，塞纳里奥的战士守卫着它的小径。巨树顶端住着{link:keeper-ordanus}守护者奥达努斯{/link}，他是{link:cenarius}塞纳留斯{/link}之子；当一名{link:shadow-council}暗影议会{/link}的术士想要取他性命时，他被人从{link:stonetalon-mountains}石爪{/link}的山巅秘密转移到了这里。牡鹿和巨熊在下方的山坡上游荡，夜刃豹{link:shadumbra}猎影{/link}在它们之间狩猎。]=],
		},
	},
})

Translate("zhCN", "the-howling-vale", {
	title = "狼嚎谷",
	aliases = { "狼嚎谷", "梅尔桑迪斯" },
	sections = {
		{
			title = "概述",
			text = [=[狼嚎谷位于{link:ashenvale}灰谷{/link}北部，靠近{link:felwood}费伍德森林{/link}的边界。它的中心是梅尔桑迪斯的残破神殿，那里保存着一本奇异的书。梅尔桑迪斯本人曾祝福过它的书页，凭借一种无人能解释的力量，这些书页记下了这片土地上的重大事件。近来，狼人占据了神殿。它们令人胆寒的嚎叫让{link:stranglethorn-vale}山谷{/link}得了这个名字。那本书向{link:sentinels}哨兵{/link}揭示，这些生物与一位失踪的女祭司有关，也与一件名为{red:scythe-of-elune}艾露恩之镰{/red}的圣物有关。]=],
		},
	},
})

Translate("zhCN", "night-run", {
	title = "夜道谷",
	sections = {
		{
			title = "概述",
			text = [=[夜道谷是{link:ashenvale}灰谷{/link}东北部一座被{link:satyrs}萨特{/link}占据的{link:stranglethorn-vale}山谷{/link}。它的神殿浸透了鲜血，即使是身经百战的战士也会感到不安。上层精灵领主{link:athrikus-narassin}埃瑟里克斯·纳拉辛{/link}在这里藏起了他最后的灵魂宝石之一，一个被囚禁的上层精灵灵魂在宝石中等待，直到被释放。夜道谷的萨特还藏着从战歌偷来的油，在他们的仪式中焚烧。]=],
		},
	},
})

Translate("zhCN", "satyrnaar", {
	title = "萨提纳尔",
	sections = {
		{
			title = "概述",
			text = [=[萨提纳尔是魔麝{link:satyrs}萨特{/link}在{link:ashenvale}灰谷{/link}东部的据点，一座笼罩在邪能阴影中的废墟。它是{link:athrikus-narassin}埃瑟里克斯·纳拉辛{/link}存放灵魂宝石的地方之一，一个上层精灵的灵魂曾被囚禁于此。与{link:night-run}夜道谷{/link}和{link:xavian}萨维亚{/link}一样，它曾经是一座神殿。圣骑士{link:delgren-the-purifier}净化者德尔格伦{/link}听说，萨特的历史与{link:night-elves}暗夜精灵{/link}的历史紧密相连，但他的东道主们对此闭口不谈。]=],
		},
	},
})

Translate("zhCN", "xavian", {
	title = "萨维亚",
	sections = {
		{
			title = "概述",
			text = [=[萨维亚是一座传说中的古代精灵之城，坐落在{link:ashenvale}灰谷{/link}东部的丘陵之间。学者们讲述着它失落的知识，据说它最高的瀑布之水蕴含着强大的魔力。如今萨维亚的{link:satyrs}萨特{/link}统治着它的废墟，其中有盗贼、邪誓者和地狱召唤者。他们的首领{link:geltharis}加萨里斯{/link}从树妖那里偷走了{link:cenarius}塞纳留斯{/link}之枝。三位树妖姐妹进入萨维亚想把它夺回来。只有一位活着出来，而且没能活多久。]=],
		},
	},
})

Translate("zhCN", "forest-song", {
	title = "林歌神殿",
	aliases = { "夜歌森林" },
	sections = {
		{
			title = "概述",
			text = [=[林歌神殿是{link:night-elves}暗夜精灵{/link}在{link:ashenvale}灰谷{/link}东部夜歌森林中的一座神殿，靠近{link:azshara}艾萨拉{/link}的边界。德鲁伊{link:kayneth-stillwind}凯尼斯·静风{/link}看守着它。他在这里阅读{link:sentinels}哨兵{/link}的报告，从中寻找他所担忧的、正在森林中蔓延的邪恶迹象。神殿离{link:horde}部落{/link}的伐木营地和{link:xavian}萨维亚{/link}的{link:satyrs}萨特{/link}废墟都很近，它的德鲁伊很少能安然入睡。]=],
		},
	},
})

Translate("zhCN", "bough-shadow", {
	title = "大树荫",
	sections = {
		{
			title = "概述",
			text = [=[大树荫是{link:ashenvale}灰谷{/link}最东北角的一棵巨树，位于{link:forest-song}林歌神殿{/link}之外。德鲁伊说，它是通往{link:emerald-dream}翡翠梦境{/link}的四棵巨树之一。绿色龙人在树下守卫，巨大的绿色幼龙在树冠上空盘旋。它们不容任何人靠近，林歌神殿的精灵也不去打扰它们。]=],
		},
	},
})

Translate("zhCN", "splintertree-post", {
	title = "碎木岗哨",
	aliases = { "碎木" },
	sections = {
		{
			title = "概述",
			text = [=[碎木岗哨是{link:horde}部落{/link}在{link:ashenvale}灰谷{/link}东部的据点，一座建在山丘上、俯瞰通往{link:the-barrens}贫瘠之地{/link}道路的{link:orcs}兽人{/link}小屋围寨。它守护着{link:warsong-lumber-camp}战歌伐木营地{/link}，以及把木材运往南方的道路。它的战士、猎人和商人来自部落的每一个种族。{link:mastok-wrilehiss}马斯托克·维尔西斯{/link}在门口发着牢骚，{link:senani-thunderheart}塞娜尼·雷心{/link}为年轻猎手设下考验，{link:ertog-ragetusk}埃尔托格·怒齿{/link}策划着对精灵的袭击。那里很少有一夜不响起警报。]=],
		},
	},
})

Translate("zhCN", "warsong-lumber-camp", {
	title = "战歌伐木营地",
	aliases = { "战歌劳工营地" },
	sections = {
		{
			title = "概述",
			text = [=[战歌伐木营地位于{link:ashenvale}灰谷{/link}最东部，靠近将森林与{link:azshara}艾萨拉{/link}分开的河流。战歌氏族的苦工在这里砍伐精灵的巨树，把木材运往南方，为{link:horde}部落{/link}建造家园、提供燃料。地精伐木机在树桩间轰鸣，步兵保护工人免受{link:sentinels}哨兵{/link}的箭矢。正是这项劳作在{link:third-war}第三次战争{/link}中把{link:grom-hellscream}格罗姆·地狱咆哮{/link}带到了灰谷，而它从未停止。营地依赖补给为生：来自{link:ratchet}棘齿城{/link}的锯片，来自{link:booty-bay}藏宝海湾{/link}的斧头，还有总被{link:satyrs}萨特{/link}和{link:furbolgs}熊怪{/link}偷走的油和绳索。]=],
		},
	},
})

Translate("zhCN", "demon-fall-canyon", {
	title = "屠魔峡谷",
	aliases = { "屠魔山", "屠魔峡谷", "冥火岭" },
	sections = {
		{
			title = "概述",
			text = [=[屠魔峡谷是{link:ashenvale}灰谷{/link}东南部的一道深谷，它的名字纪念着{link:third-war}第三次战争{/link}中最著名的事迹。在这片森林的一条峡谷中，{link:grom-hellscream}格罗姆·地狱咆哮{/link}把战斧劈进了深渊领主{link:mannoroth}玛诺洛斯{/link}的身体，将{link:orcs}兽人{/link}从恶魔之血中解放出来，并在那里死去。峡谷从未被净化。恶魔卫士在其中守卫，地狱火在岩石间闷燃，军团猎犬在上方的山脊上狩猎。在南边的冥火岭上，一个名为寻觅者迪亚索鲁斯的恐惧魔王统领着它们。]=],
		},
	},
})

Translate("zhCN", "the-dor-danil-barrow-den", {
	title = "朵丹尼尔兽穴",
	aliases = { "朵丹尼尔兽穴", "朵丹尼尔" },
	sections = {
		{
			title = "概述",
			text = [=[朵丹尼尔兽穴位于{link:ashenvale}灰谷{/link}东南部，在通往{link:the-barrens}贫瘠之地{/link}的道路以东。这里的德鲁伊曾在此沉睡，并保管着一根古老法杖的一部分。后来{link:forsaken}被遗忘者{/link}来了。他们在兽穴旁建起营地，调制他们的疾病，在德鲁伊沉睡时毒害了他们。朵丹尼尔德鲁伊的灵魂与肉体分离，陷入疯狂，如今与杀害他们的亡灵一同在兽穴中游荡。]=],
		},
	},
})

Translate("zhCN", "silverwing-outpost", {
	title = "银翼哨站",
	aliases = { "银翼树林" },
	sections = {
		{
			title = "概述",
			text = [=[银翼哨站是{link:sentinels}哨兵{/link}在{link:ashenvale}灰谷{/link}南部的一座营地，坐落在{link:horde}部落{/link}伐木道路以西的林中。它的斥候穿行林间，刺探{link:orcs}兽人{/link}的动静，它的战士随时准备进攻{link:splintertree-post}碎木{/link}。{link:duriel-moonfire}杜瑞尔·月火{/link}统领着它。部落视它为肋下的一把匕首，部落的袭击者已发誓要拿下它。]=],
		},
	},
})

Translate("zhCN", "bloodtooth-camp", {
	title = "血牙营地",
	aliases = { "血牙" },
	sections = {
		{
			title = "概述",
			text = [=[血牙营地是{link:furbolgs}熊怪{/link}{link:ran-bloodtooth}兰恩·血牙{/link}及其护卫的巢穴，位于{link:ashenvale}灰谷{/link}南部，靠近{link:the-barrens}贫瘠之地{/link}的边缘。拉恩是被腐化的熊怪中最凶猛的一个，是同族中的王者，而腐化只让他变得更加强大。就连其他熊怪也惧怕从这座营地中出来的东西。]=],
		},
	},
})

Translate("zhCN", "greenpaw-village", {
	title = "绿爪村",
	aliases = { "污林图腾丘" },
	sections = {
		{
			title = "概述",
			text = [=[绿爪村是污林{link:furbolgs}熊怪{/link}的家园，位于{link:astranaar}阿斯特兰纳{/link}以东道路的南侧、弗伦河以西。部族的图腾丘矗立在村子中心。污林比{link:thistlefur-village}蓟皮{/link}人数少，却更加凶猛，他们会袭击路上的旅人。{link:sentinels}哨兵{/link}和{link:horde}部落{/link}都曾向他们出击。当一面部落的旗帜插上他们的图腾丘时，他们的酋长出来捍卫部族的荣誉，并因此倒下。]=],
		},
	},
})

Translate("zhCN", "raene-wolfrunner", {
	title = "莱恩·狼行者",
	subtitle = "阿斯特兰纳哨兵指挥官",
	found = "阿斯特兰纳，在她的两只野兽身旁",
	hint = "与统领阿斯特兰纳哨兵的女猎手交谈。",
	allegiance = "哨兵 · 达纳苏斯",
	aliases = { "莱恩" },
	sections = {
		{
			title = "概述",
			text = [=[莱恩·狼行者统领着{link:astranaar}阿斯特兰纳{/link}的{link:sentinels}哨兵{/link}。她是一位女猎手，身边带着一头狼和一只大猫，森林中的每一份报告都要经过她的手。她向远至{link:darkshore}黑海岸{/link}的地方求援，前来响应的人会发现她冷静、严肃，而且极度缺少战士。]=],
		},
		{
			title = "意义",
			text = [=[在敌人从四面八方压来的时刻，莱恩为{link:night-elves}暗夜精灵{/link}守住了{link:ashenvale}灰谷{/link}的心脏。她同时在两条战线上作战：对抗{link:horde}部落{/link}，也对抗那将森林中的{link:furbolgs}熊怪{/link}变成野兽的腐化。]=],
		},
		{
			title = "事迹",
			text = [=[• 她派出斥候和志愿者对抗{link:thistlefur-village}蓟皮{/link}与污林{link:furbolgs}熊怪{/link}。
• 她在朋友{link:teronis}泰洛尼斯{/link}死后接手了他的事业。
• 她把一位熊怪之王的头骨和一根古老的法杖陈列在{link:astranaar}阿斯特兰纳{/link}的荣誉之处。]=],
		},
	},
	chapters = {
		{
			title = "泰洛尼斯之死",
			hint = "到西边的一座岛上寻找莱恩失踪朋友的消息。",
			text = [=[莱恩的朋友{link:teronis}泰洛尼斯{/link}向西前往{link:lake-falathim}法拉希姆湖{/link}寻找一颗宝石，再也没有回来。他一直在搜寻一位已死的巫师达托尔所造法杖的碎片，他相信这根法杖能延缓{link:furbolgs}熊怪{/link}的进攻。人们在岛上发现了他的尸体，身上满是{link:murlocs}鱼人{/link}爪子的伤痕。莱恩放下了悲伤。哀悼的时刻以后自会到来。眼下要紧的是，不能让他的心血白费。]=],
		},
		{
			title = "达托尔之杖",
			hint = "收集法杖的碎片，去月亮井旁寻找那位树妖。",
			text = [=[根据{link:teronis}泰洛尼斯{/link}日志中的记录，达托尔之杖的碎片在森林各处被一一找到：一块由费伍德附近被腐化的树人看守，一块与{link:the-dor-danil-barrow-den}朵丹尼尔{/link}那些厄运缠身的德鲁伊藏在一起。树妖{link:shael-dryn}莎尔蒂恩{/link}把它们拼合起来，一座隐秘的神殿又让法杖重获力量。它能让持有者化身为{link:furbolgs}熊怪{/link}的模样。莱恩不知道泰洛尼斯原本打算拿它做什么。她猜想，他希望与一个尚未被邪能苔藓沾染的熊怪交谈。]=],
		},
		{
